"""Dependency-free static dashboard builder. findings.json is the canonical row register."""
import json, csv, html
from pathlib import Path
D=json.loads(Path('data/findings.json').read_text()); E=lambda s:html.escape(str(s),quote=True)
P={'summary':('Executive summary','Your coverage, without the guesswork.','Start here: income eligibility and the work requirement are two separate tests.'),'income':('Income & trading','Zero wages ≠ zero income.','How rent, interest and trading fit into the framework — and what remains unresolved.'),'options':('Compliance options','More than one way to qualify.','Compare income, activity and education pathways. No route is a personal approval.'),'law':('Law & timeline','What changes, and when.','Enacted federal requirements, state implementation and procedural protections.'),'exemptions':('Exclusions & exceptions','Check whether the rule applies.','These categories require their actual conditions to be met. None is assumed for you.'),'california':('California support','The California picture.','Medi-Cal eligibility, state assistance and resources for keeping coverage.'),'next-steps':('Coverage roadmap','A practical path forward.','Research completed without requesting personal information. Enrollment itself requires an accurate application.'),'review':('Flagged for Review','Uncertainty, made visible.','Blank confirmed-value cells are intentional. Context links are not proof of an unresolved claim.'),'sources':('Source library','Follow the evidence.','Official agency and legislative sources checked October 18, 2026. This is a dated research snapshot.')}
def file(k):return 'index.html' if k=='summary' else k+'.html'
def source(k):
 s=D['sources'][k];return f'<a href="{E(s["url"])}" target="_blank" rel="noopener noreferrer">{E(s["title"])} ↗</a><small>{E(s["locator"])}</small>'
def table(rows):
 t='<div class="table-wrap"><table><caption class="sr-only">Source-linked findings; blank confirmed values are unverified</caption><thead><tr><th scope="col">Topic</th><th scope="col">Confirmed value / rule</th><th scope="col">Details & implications</th><th scope="col">Evidence & status</th></tr></thead><tbody>'
 for r in rows:
  cls='ok' if r['status']=='Source-supported' else 'warn'
  t+=f'<tr id="{r["id"]}"><th scope="row"><span class="rowid">{r["id"]}</span>{E(r["item"])}</th><td>{E(r["value"])}</td><td>{E(r["detail"])}</td><td><span class="badge {cls}">{E(r["status"])}</span>'+''.join(source(k) for k in r['sources'])+'<small>Checked '+E(r['checked'])+'</small></td></tr>'
 return t+'</tbody></table></div>'
for k,(label,title,desc) in P.items():
 nav=""
 for i,(n,v) in enumerate(P.items(),1):nav+=f'<a '+('aria-current="page" ' if k==n else '')+f'href="{file(n)}"><span>{i:02}</span>{E(v[0])}</a>'
 rows=[r for r in D['rows'] if r['page']==k]
 if k=='review':rows=[r for r in D['rows'] if r['status'] not in ('Source-supported','Recommendation')]
 body=''
 if k=='summary':
  body='''<section class="hero"><div><p class="eyebrow">THE KEY DISTINCTION</p><h2>You may not need<br>earned income.</h2><p>The income-based alternative uses monthly MAGI-based household income. Net rent and interest can matter even when wages are zero. Your total income must still meet Medi-Cal financial eligibility rules.</p><a class="button" href="options.html">Explore your pathways →</a><p class="hero-source">Evidence: '''+source('deck')+source('income')+'''</p></div><aside><span class="metric">$580</span><p>Monthly income alternative<br>at the current federal minimum wage</p><hr><span class="metric">80 hrs</span><p>Activity alternative in a qualifying month<br>Not an additional requirement if the income route is met.</p>'''+source('cms')+'''</aside></section><div class="tiles"><a href="income.html"><span>01 / UNDERSTAND</span><h3>Count the right income ↗</h3><p>Rent, interest and trading</p></a><a href="exemptions.html"><span>02 / CHECK</span><h3>Review exclusions ↗</h3><p>Who may not need activity hours</p></a><a href="review.html"><span>03 / TAKE CARE</span><h3>Read the open questions ↗</h3><p>Timing, terminology and Kalshi</p></a></div>'''
 if k=='review':
  body='<div class="notice"><strong>Two material source conflicts</strong><p>Timing: the DHCS public page says January 1 for work rules; the September outreach enclosure says March. Income wording: the public page describes job earnings, while CMS uses MAGI and the enclosure says “any source.” Both versions are linked below. Do not assume that a generic page overrides an individual county notice.</p>'+source('changes')+source('notice')+source('deck')+'</div>'
 if k=='sources':
  body='<div class="notice"><strong>Verification standard</strong><p>Each finding has a stable row ID, an official source, a locator and a review date. “Source-supported” means the stated general rule was checked, not that personal eligibility is established. Recommendations are labeled. Unconfirmed values are blank; absence of a verified answer is not proof that no answer exists. External sources were opened with the research retrieval tool; no continuous monitoring is implied.</p><p>FederalRegister.gov supplies agency text but is not the official legal edition; consult the linked GovInfo PDF for legal reliance. The long federal rule and statute were reviewed by relevant provisions, not certified in their entirety. Scope: the stated California citizen scenario, not an exhaustive review of every healthcare program.</p></div>'
  body+='<div class="table-wrap"><table><thead><tr><th>Official source</th><th>Review locator</th><th>Checked</th></tr></thead><tbody>'+''.join('<tr><th>'+source(s)+'</th><td>'+E(v['locator'])+'</td><td>'+E(v['checked'])+'</td></tr>' for s,v in D['sources'].items())+'</tbody></table></div>'
  body+='<p><a href="data/findings.json" download>Download the complete JSON register</a> · <a href="data/findings.csv" download>Download CSV</a></p>'
 else:
  body+='<section class="findings"><div class="section-head"><div><p class="eyebrow">RESEARCH REGISTER</p><h2>'+('Open items & cautions' if k=='review' else 'Findings at a glance')+'</h2></div><span>'+str(len(rows))+' entries · official sources</span></div><label class="search-label">Filter this table <input type="search" id="search" placeholder="Search topics, rules or sources…"></label><p id="result-count" aria-live="polite"></p>'+table(rows)+'</section>'
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Source-linked California healthcare and Medicaid community engagement research, as of October 18, 2026."><title>{E(label)} · California Coverage Guide</title><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><aside class="sidebar"><a class="brand" href="index.html"><span class="brand-icon">+</span><span>Coverage<span class="brand-light"> / California</span></span></a><p class="sidebar-label">RESEARCH DASHBOARD</p><nav aria-label="Main navigation">{nav}</nav><div class="sidebar-bottom"><span class="dot"></span> Official-source research<p>Public information, not an eligibility decision.</p></div></aside><div class="workspace"><header><span>CALIFORNIA HEALTHCARE / {E(label.upper())}</span><span class="date">Reviewed · 18 Oct 2026</span></header><main id="main"><div class="page-title"><p class="eyebrow">COVERAGE CLARITY</p><h1>{E(title)}</h1><p>{E(desc)}</p></div><div class="alert"><span>!</span><p><strong>2027 transition: important details remain unsettled.</strong> Read the <a href="review.html">Flagged for Review</a> page before relying on a start date or on personal trading hours.</p></div>{body}<footer><strong>Research, not a coverage guarantee.</strong><p>Prepared for a U.S. citizen residing in California with no wage income. Age, household, income amounts, health status and enrollment category are unknown. No personal values are invented. All amounts are dated; rules can change.</p><a href="sources.html">Methodology & sources</a> · <a href="data/findings.csv" download>Export findings</a><p>No tracking, accounts or personal-data collection. Static research snapshot: 2026-10-18.</p></footer></main></div></body></html>'''
 Path(file(k)).write_text(doc)
with open('data/findings.csv','w') as f:
 w=csv.writer(f);w.writerow(['ID','Category','Topic','Confirmed value','Details','Status','Official sources','Checked'])
 for r in D['rows']:w.writerow([r['id'],r['page'],r['item'],r['value'],r['detail'],r['status'],' | '.join(D['sources'][s]['url'] for s in r['sources']),r['checked']])
print(f'Built {len(P)} pages, {len(D["rows"])} findings, {len(D["sources"])} sources')
